package com.ejemplo.msb.service;
import com.ejemplo.msb.client.ProgramaEducativoFeignMSA;import com.ejemplo.msb.dto.*;import com.ejemplo.msb.entity.*;import com.ejemplo.msb.repository.EntityBRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;import java.util.stream.Collectors;
@Service public class EntityBService {private final EntityBRepository repo;private final ProgramaEducativoFeignMSA msa;public EntityBService(EntityBRepository r,ProgramaEducativoFeignMSA c){repo=r;msa=c;}private List<EntityADto> getDivisiones(List<Long> ids){if(ids==null||ids.isEmpty())return List.of();List<EntityADto> got=msa.obtenerDTOsDelMSA(ids);if(got==null||got.size()!=new HashSet<>(ids).size())throw new IllegalArgumentException("Una o más divisiones no existen o no se pudieron consultar en MS-A");Set<Long> valid=got.stream().map(EntityADto::getId).collect(Collectors.toSet());if(!valid.containsAll(ids))throw new IllegalArgumentException("Una o más divisiones no existen en MS-A");return got;}private EntityBDtoList map(EntityB b,Map<Long,EntityADto> divs){var d=new EntityBDtoList();d.setId(b.getId());d.setNombreB(b.getNombreB());var ids=b.getListaConEntityA().stream().map(EntityBEntityA::getEntityAId).distinct().toList();d.setEntityAIds(ids);d.setDivisiones(ids.stream().map(divs::get).filter(Objects::nonNull).toList());return d;}@Transactional public EntityBDtoList create(EntityBDto d){var divisions=getDivisiones(d.getEntityAIds());var b=new EntityB();b.setNombreB(d.getNombreB().trim());d.getEntityAIds().stream().distinct().forEach(b::addDivision);var saved=repo.save(b);return map(saved,divisions.stream().collect(Collectors.toMap(EntityADto::getId,x->x)));}@Transactional(readOnly=true)public List<EntityBDtoList> findAll(){var bs=repo.findAll();var ids=bs.stream().flatMap(b->b.getListaConEntityA().stream()).map(EntityBEntityA::getEntityAId).distinct().toList();List<EntityADto> divisions=ids.isEmpty()?List.of():msa.obtenerDTOsDelMSA(ids);Map<Long,EntityADto> m=divisions==null?Map.of():divisions.stream().collect(Collectors.toMap(EntityADto::getId,x->x,(a,b)->a));return bs.stream().map(b->map(b,m)).toList();}@Transactional(readOnly=true)public Optional<EntityBDtoList> findById(Long id){return repo.findById(id).map(b->{var ids=b.getListaConEntityA().stream().map(EntityBEntityA::getEntityAId).distinct().toList();var ds=ids.isEmpty()?List.<EntityADto>of():msa.obtenerDTOsDelMSA(ids);var m=ds==null?Map.<Long,EntityADto>of():ds.stream().collect(Collectors.toMap(EntityADto::getId,x->x,(a,c)->a));return map(b,m);});}@Transactional public Optional<EntityBDtoList> update(Long id,EntityBDto d){return repo.findById(id).map(b->{var divisions=getDivisiones(d.getEntityAIds());b.setNombreB(d.getNombreB().trim());b.getListaConEntityA().clear();d.getEntityAIds().stream().distinct().forEach(b::addDivision);return map(repo.save(b),divisions.stream().collect(Collectors.toMap(EntityADto::getId,x->x)));});}public boolean usesDivision(Long divisionId){return repo.existsByListaConEntityA_EntityAId(divisionId);}public boolean delete(Long id){if(!repo.existsById(id))return false;repo.deleteById(id);return true;}}
